package android.content;import java.util.*;public class Intent {public String action,pkg;public Map<String,Object> extras=new HashMap<>();public String getAction(){return action;}public String getStringExtra(String k){return (String)extras.get(k);}public long getLongExtra(String k,long fallback){Object v=extras.get(k);return v==null?fallback:(Long)v;}public Intent(String a){action=a;}public Intent setPackage(String p){pkg=p;return this;}public Intent putExtra(String k,int v){extras.put(k,v);return this;}public Intent putExtra(String k,long v){extras.put(k,v);return this;}public Intent putExtra(String k,String v){extras.put(k,v);return this;}}
